import { SaveSystem } from '../systems/SaveSystem.js';
import { GameScene } from './GameScene.js';
const fmtPlay=s=>{s=Math.floor(s||0);return`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor((s%3600)/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
export class TitleScene {
  constructor(game){this.game=game;this.t=0;this.screen='main';this.buttons=[];}
  init(){this.game.sound.ensure?.();this.game.sound.setDucked(false);}
  update(dt){this.t+=dt;const i=this.game.input;if(this.screen==='main'){if(i.hit('Digit1','Numpad1','KeyN'))this.startNew();if(i.hit('Digit2','Numpad2','KeyC')&&SaveSystem.hasAnySave())this.screen='load';if(i.click)this.clickButtons(i.click);}else if(this.screen==='load'){if(i.hit('Escape'))this.screen='main';if(i.click)this.clickButtons(i.click);}else if(this.screen==='options'){if(i.hit('Escape'))this.screen='main';if(i.click)this.handleOptionsClick(i.click);}}
  clickButtons(p){for(const b of this.buttons){if(p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h&&b.enabled!==false){b.action();return;}}}
  startNew(){this.game.sound.coin();this.game.sound.startBGM();this.game.scenes.set(GameScene,{newGame:true});}
  loadSlot(id){const data=SaveSystem.load(id);if(!data)return;this.game.sound.coin();this.game.sound.startBGM();this.game.scenes.set(GameScene,{save:data,loadedSlot:id});}
  handleOptionsClick(p){const a=this.game.sound,sx=252,sw=176;if(p.y>=147&&p.y<=166&&p.x>=sx&&p.x<=sx+sw){a.setBGMVolume((p.x-sx)/sw);return;}if(p.y>=212&&p.y<=231&&p.x>=sx&&p.x<=sx+sw){a.setSFXVolume((p.x-sx)/sw);a.tone(500,.05,'square',.03);return;}for(const b of this.buttons){if(p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h){b.action();return;}}}
  render(ctx){this.drawBg(ctx);if(this.screen==='main')this.renderMain(ctx);else if(this.screen==='load')this.renderLoad(ctx);else this.renderOptions(ctx);}
  drawBg(ctx){ctx.fillStyle='#3d332a';ctx.fillRect(0,0,640,360);for(let y=0;y<360;y+=24){for(let x=((y/24)%2)*20-20;x<640;x+=40){ctx.fillStyle=((x+y)/8)%2?'#493c30':'#42362c';ctx.fillRect(x,y,38,22);}}const glow=.5+.5*Math.sin(this.t*2);ctx.fillStyle=`rgba(235,115,38,${.08+glow*.06})`;ctx.fillRect(0,0,640,360);}
  title(ctx,sub=''){ctx.fillStyle='#1c120d';ctx.fillRect(78,35,484,126);ctx.fillStyle='#7f5935';ctx.fillRect(84,41,472,114);ctx.fillStyle='#4f321f';ctx.fillRect(92,49,456,98);ctx.fillStyle='#d1a45e';ctx.fillRect(106,62,428,3);ctx.fillRect(106,136,428,3);ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#f1d7a2';ctx.font='bold 24px monospace';ctx.fillText('형제 대장간',320,91);ctx.fillStyle='#d8ba84';ctx.font='10px monospace';ctx.fillText('BLACKSMITH BROTHERS · V0.2.4 UX & V0.2.3 SYSTEMS',320,117);ctx.fillStyle='#bfa378';ctx.font='8px monospace';ctx.fillText(sub||'달력·임대료·정밀 제작·진상 다양화·다중 세이브·BGM',320,132);ctx.textAlign='left';}
  renderMain(ctx){this.title(ctx);const has=SaveSystem.hasAnySave(),opts=[{label:'1. 새 게임',enabled:true,action:()=>this.startNew()},{label:'2. 이어하기',enabled:has,action:()=>this.screen='load'},{label:'3. 옵션',enabled:true,action:()=>this.screen='options'}];this.buttons=[];opts.forEach((o,i)=>{const x=210,y=190+i*45,w=220,h=32;this.buttons.push({...o,x,y,w,h});ctx.fillStyle=o.enabled?'#2a1c13':'#241c17';ctx.fillRect(x,y,w,h);ctx.fillStyle=o.enabled?'#9c7145':'#5e5145';ctx.fillRect(x+2,y+2,w-4,h-4);ctx.fillStyle=o.enabled?'#20150f':'#302923';ctx.fillRect(x+5,y+5,w-10,h-10);ctx.fillStyle=o.enabled?'#f0d9ad':'#796d60';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText(o.label,x+w/2,y+h/2);});ctx.fillStyle='#c3a87a';ctx.font='8px monospace';ctx.fillText('The Artisan\'s Hearth · 새 게임/불러오기 시 재생 · ESC 일시정지 메뉴',320,343);ctx.textAlign='left';}
  renderLoad(ctx){this.title(ctx,'AUTO SAVE와 SAVE 1~6 중 원하는 시점을 선택');this.buttons=[];const slots=SaveSystem.list();slots.forEach((s,i)=>{const x=128,y=168+i*26,w=384,h=23,m=s.meta;const enabled=!!m;this.buttons.push({x,y,w,h,enabled,action:()=>this.loadSlot(s.id)});ctx.fillStyle=enabled?'#24170f':'#30271f';ctx.fillRect(x,y,w,h);ctx.strokeStyle=enabled?'#9b7042':'#584b3f';ctx.strokeRect(x+.5,y+.5,w-1,h-1);ctx.fillStyle=enabled?'#f0d7aa':'#776b5f';ctx.font='bold 8px monospace';ctx.fillText(s.label,x+7,y+9);ctx.font='7px monospace';if(m&&!m.corrupt)ctx.fillText(`${m.date} ${m.time} · ${m.gold}G · 평판 ${m.reputation} · ${fmtPlay(m.playTimeSeconds)}`,x+82,y+14);else ctx.fillText(m?.corrupt?'손상된 저장':'비어 있음',x+82,y+14);});const b={x:264,y:342,w:112,h:16,action:()=>this.screen='main'};this.buttons.push(b);ctx.fillStyle='#2a1b12';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#ead2a7';ctx.textAlign='center';ctx.font='8px monospace';ctx.fillText('ESC / 뒤로',320,351);ctx.textAlign='left';}
  renderOptions(ctx){this.title(ctx,'전체 세이브에 공통으로 유지되는 오디오 설정');const a=this.game.sound;ctx.fillStyle='#ead5ae';ctx.font='10px monospace';ctx.fillText(`BGM ${Math.round(a.bgmVolume*100)}%`,164,154);this.slider(ctx,252,147,176,a.bgmVolume);ctx.fillText(`효과음 ${Math.round(a.sfxVolume*100)}%`,164,219);this.slider(ctx,252,212,176,a.sfxVolume);this.buttons=[{x:239,y:272,w:162,h:27,action:()=>this.screen='main'}];ctx.fillStyle='#2a1b12';ctx.fillRect(239,272,162,27);ctx.strokeStyle='#9d7040';ctx.strokeRect(239.5,272.5,161,26);ctx.fillStyle='#efd8ad';ctx.textAlign='center';ctx.fillText('뒤로',320,287);ctx.fillStyle='#ae9672';ctx.font='8px monospace';ctx.fillText('슬라이더를 클릭하면 즉시 반영됩니다.',320,322);ctx.textAlign='left';}
  slider(ctx,x,y,w,v){ctx.fillStyle='#251811';ctx.fillRect(x,y,w,19);ctx.fillStyle='#815b35';ctx.fillRect(x+5,y+8,w-10,4);ctx.fillStyle='#ddb962';ctx.fillRect(x+5,y+8,(w-10)*v,4);ctx.fillStyle='#f1ddaa';ctx.fillRect(x+Math.round((w-12)*v),y+3,7,13);}
}
